/* Pure C clause implementations */
int skode_clause_wave_1(int voice, const float *args, int argc) {
    (void)argc;
    int x = (int)args[0];
    if (voice < 0 || voice >= synth_config.voice_max) return -1;
    if ((float)x != args[0]) return -1;
    if (wave_set(voice, x) != 0) return -1;
    sv.one_shot[voice] = sw.one_shot[x];
    osc_reclassify(&skred_global_engine, voice);
    return 0;

}

static int skode_clause_wave_1_imm_bridge(skode_t *ctx, ands_t *s, const double *args, int argc) {
    float fargs[SKODE_CLAUSE_MAX_ARGS];
    int i;
    (void)s;
    for (i = 0; i < argc && i < SKODE_CLAUSE_MAX_ARGS; i++) fargs[i] = (float)args[i];
    return skode_clause_wave_1(ctx ? ctx->voice : 0, fargs, argc);
}

int skode_clause_wave_2(int voice, const float *args, int argc) {
    (void)argc;
    int x = (int)args[0];
    int interp = (int)args[1];
    if (voice < 0 || voice >= synth_config.voice_max) return -1;
    if ((float)x != args[0] || (float)interp != args[1]) return -1;
    if (wave_set(voice, x) != 0) return -1;
    sv.interpolate[voice] = interp != 0;
    sv.one_shot[voice] = sw.one_shot[x];
    osc_reclassify(&skred_global_engine, voice);
    return 0;

}

static int skode_clause_wave_2_imm_bridge(skode_t *ctx, ands_t *s, const double *args, int argc) {
    float fargs[SKODE_CLAUSE_MAX_ARGS];
    int i;
    (void)s;
    for (i = 0; i < argc && i < SKODE_CLAUSE_MAX_ARGS; i++) fargs[i] = (float)args[i];
    return skode_clause_wave_2(ctx ? ctx->voice : 0, fargs, argc);
}

int skode_clause_wave_3(int voice, const float *args, int argc) {
    (void)argc;
    int x = (int)args[0];
    int interp = (int)args[1];
    int shot = (int)args[2];
    if (voice < 0 || voice >= synth_config.voice_max) return -1;
    if ((float)x != args[0] || (float)interp != args[1] || (float)shot != args[2]) return -1;
    if (wave_set(voice, x) != 0) return -1;
    sv.interpolate[voice] = interp != 0;
    sv.one_shot[voice] = shot != 0;
    osc_reclassify(&skred_global_engine, voice);
    return 0;

}

