int skode_clause_voice_link_trig_1(int voice, const float *args, int argc) {
    (void)argc;
    if (voice < 0 || voice >= synth_config.voice_max) return -1;
    if (args[0] <= 0.0f) {
        sv.link_trig[voice] = -1.0f;
        sv.link_trig_samp[voice] = 0;
    } else {
        long double samples = (long double)args[0] * MAIN_SAMPLE_RATE;
        sv.link_trig[voice] = args[0];
        sv.link_trig_samp[voice] = samples >= (long double)UINT64_MAX ?
            UINT64_MAX : (uint64_t)samples;
    }
    return 0;

}

static int skode_clause_voice_link_trig_1_imm_bridge(skode_t *ctx, ands_t *s, const double *args, int argc) {
    float fargs[SKODE_CLAUSE_MAX_ARGS];
    int i;
    (void)s;
    for (i = 0; i < argc && i < SKODE_CLAUSE_MAX_ARGS; i++) fargs[i] = (float)args[i];
    return skode_clause_voice_link_trig_1(ctx ? ctx->voice : 0, fargs, argc);
}

int skode_clause_voice_link_trig_0(int voice, const float *args, int argc) {
    (void)argc;
    if (voice < 0 || voice >= synth_config.voice_max) return -1;
    sv.link_trig[voice] = -1.0f;
    sv.link_trig_samp[voice] = 0;
    return 0;

}

