const skode_def_word_t *skode_dict_find(const char *name_or_alias) {
    if (!name_or_alias || !name_or_alias[0]) return NULL;
    uint32_t h = 5381;
    const unsigned char *p = (const unsigned char *)name_or_alias;
    while (*p) h = ((h << 5) + h) + *p++;
    uint32_t idx = h & (2048 - 1);
    for (uint32_t step = 0; step < 2048; step++) {
        uint16_t w_idx = s_dict_hash_table[(idx + step) & (2048 - 1)];
        if (w_idx == 0xFFFF) return NULL;
        const skode_def_word_t *w = &g_skode_words[w_idx];
        if (strcmp(w->name, name_or_alias) == 0) return w;
        if (w->alias && strcmp(w->alias, name_or_alias) == 0) return w;
    }
    return NULL;
}

static int arg_matches(double val, skode_arg_class_t cls) {
    switch (cls) {
        case MATCH_ANY:    return 1;
        case MATCH_NUM:    return 1;
        case MATCH_FINITE: return isfinite(val);
        case MATCH_NAN:    return isnan(val);
        case MATCH_INF_POS: return isinf(val) && val > 0.0;
        case MATCH_INF_NEG: return isinf(val) && val < 0.0;
        case MATCH_ATOM:   return 1;
        default:           return 0;
    }
}

const skode_clause_t *skode_clause_match_ex(const skode_def_word_t *word, int argc, const double *args, unsigned var_mask) {
    uint8_t i;
    if (!word) return NULL;
    for (i = 0; i < word->clause_count; i++) {
        const skode_clause_t *c = &word->clauses[i];
        int match = 1;
        int a;
        if (argc < c->min_arity || argc > c->max_arity) continue;
        for (a = 0; a < argc; a++) {
            if (var_mask & (1U << a)) {
                if (c->match[a] != MATCH_ANY && c->match[a] != MATCH_NUM && c->match[a] != MATCH_FINITE) {
                    match = 0;
                    break;
                }
                continue;
            }
            if (!arg_matches(args[a], c->match[a])) {
                match = 0;
                break;
            }
        }
        if (match && c->guard && !c->guard(args, argc)) {
            match = 0;
        }
        if (match) return c;
    }
    return NULL;
}

const skode_clause_t *skode_clause_match(const skode_def_word_t *word, int argc, const double *args) {
    return skode_clause_match_ex(word, argc, args, 0);
}

static const char *s_arg_class_name(skode_arg_class_t cls) {
    switch (cls) {
        case MATCH_ANY: return "any";
        case MATCH_NUM: return "num";
        case MATCH_FINITE: return "finite";
        case MATCH_NAN: return "nan";
        case MATCH_INF_POS: return "+inf";
        case MATCH_INF_NEG: return "-inf";
        case MATCH_ATOM: return ":atom";
        default: return "any";
    }
}

void skode_clause_explain_mismatch(const skode_def_word_t *word, int argc, const double *args, char *buf, size_t buf_size) {
    if (!buf || buf_size == 0) return;
    buf[0] = '\0';
    if (!word) {
        snprintf(buf, buf_size, "unknown command");
        return;
    }
    uint8_t arities[16];
    int arity_count = 0;
    int has_matching_arity = 0;
    uint8_t i;
    for (i = 0; i < word->clause_count; i++) {
        const skode_clause_t *c = &word->clauses[i];
        if (argc >= c->min_arity && argc <= c->max_arity) has_matching_arity = 1;
        for (uint8_t ar = c->min_arity; ar <= c->max_arity; ar++) {
            int found = 0;
            for (int j = 0; j < arity_count; j++) {
                if (arities[j] == ar) { found = 1; break; }
            }
            if (!found && arity_count < 16) arities[arity_count++] = ar;
        }
    }
    if (!has_matching_arity) {
        char ar_str[64] = "";
        for (int j = 0; j < arity_count; j++) {
            char num[16];
            snprintf(num, sizeof(num), "%s%d", (j > 0 ? ", " : ""), arities[j]);
            strncat(ar_str, num, sizeof(ar_str) - strlen(ar_str) - 1);
        }
        snprintf(buf, buf_size, "expected arity [%s]", ar_str);
        return;
    }
    for (i = 0; i < word->clause_count; i++) {
        const skode_clause_t *c = &word->clauses[i];
        if (argc < c->min_arity || argc > c->max_arity) continue;
        for (int a = 0; a < argc; a++) {
            if (!arg_matches(args[a], c->match[a])) {
                const char *val_type = "unknown";
                if (isnan(args[a])) val_type = "nan";
                else if (isinf(args[a])) val_type = (args[a] > 0 ? "+inf" : "-inf");
                else val_type = "finite";
                snprintf(buf, buf_size, "clause %d expected arg %d as %s, got %s (%g)",
                         i + 1, a, s_arg_class_name(c->match[a]), val_type, args[a]);
                return;
            }
        }
        if (c->guard && !c->guard(args, argc)) {
            snprintf(buf, buf_size, "clause %d guard condition failed", i + 1);
            return;
        }
    }
    snprintf(buf, buf_size, "clause pattern matching failed");
}

const char *skode_group_name(skode_group_t group) {
    if (group >= 0 && group < SKODE_GRP_COUNT) return s_group_names[group];
    return "sys";
}

skode_group_t skode_group_from_name(const char *name) {
    int i;
    if (!name) return SKODE_GRP_SYS;
    for (i = 0; i < SKODE_GRP_COUNT; i++) {
        if (strcmp(name, s_group_names[i]) == 0) return (skode_group_t)i;
    }
    return SKODE_GRP_SYS;
}

void skode_dict_help(FILE *out, const char *group_or_word) {
    size_t g, i;
    if (!out) out = stdout;
    if (!group_or_word || !group_or_word[0] || strcmp(group_or_word, "help") == 0) {
        fprintf(out, "Available command groups:\n");
        for (g = 0; g < SKODE_GRP_COUNT; g++) {
            size_t count = 0;
            for (i = 0; i < g_skode_words_count; i++) {
                if (g_skode_words[i].group == (skode_group_t)g) count++;
            }
            fprintf(out, "  %-8s (%zu words)\n", s_group_names[g], count);
        }
        fprintf(out, "\nType 'help <group>' to see commands in a group, or 'help <command>' for details.\n");
        return;
    }

    /* Check if group_or_word is a group name */
    for (g = 0; g < SKODE_GRP_COUNT; g++) {
        if (strcmp(group_or_word, s_group_names[g]) == 0) {
            fprintf(out, "Commands in group '%s':\n", s_group_names[g]);
            for (i = 0; i < g_skode_words_count; i++) {
                if (g_skode_words[i].group == (skode_group_t)g) {
                    const skode_def_word_t *w = &g_skode_words[i];
                    int c;
                    if (w->alias) {
                        fprintf(out, "  %-16s (alias: %-4s) [%d clause(s)]\n", w->name, w->alias, w->clause_count);
                    } else {
                        fprintf(out, "  %-16s [%d clause(s)]\n", w->name, w->clause_count);
                    }
                    for (c = 0; c < w->clause_count; c++) {
                        if (w->clauses[c].min_arity == w->clauses[c].max_arity) {
                            fprintf(out, "    clause %d (arity %d): %s\n", c + 1, w->clauses[c].min_arity,
                                    w->clauses[c].summary ? w->clauses[c].summary : "");
                        } else {
                            fprintf(out, "    clause %d (arity %d..%d): %s\n", c + 1, w->clauses[c].min_arity, w->clauses[c].max_arity,
                                    w->clauses[c].summary ? w->clauses[c].summary : "");
                        }
                    }
                }
            }
            return;
        }
    }

    /* Check if group_or_word is a command name or alias */
    {
        const skode_def_word_t *w = skode_dict_find(group_or_word);
        if (w) {
            int c;
            fprintf(out, "Command: %s\n", w->name);
            if (w->alias) fprintf(out, "Alias:   %s\n", w->alias);
            fprintf(out, "Group:   %s\n", skode_group_name(w->group));
            fprintf(out, "Clauses (%d):\n", w->clause_count);
            for (c = 0; c < w->clause_count; c++) {
                const skode_clause_t *cl = &w->clauses[c];
                if (cl->min_arity == cl->max_arity) {
                    fprintf(out, "  [%d] arity %d", c + 1, cl->min_arity);
                } else {
                    fprintf(out, "  [%d] arity %d..%d", c + 1, cl->min_arity, cl->max_arity);
                }
                if (cl->flags & SKODE_CLAUSE_RT_SAFE) fprintf(out, " (RT_SAFE)");
                if (cl->flags & SKODE_CLAUSE_IMMEDIATE) fprintf(out, " (IMMEDIATE)");
                if (cl->flags & SKODE_CLAUSE_NEEDS_STRING) fprintf(out, " [NEEDS_STRING]");
                if (cl->flags & SKODE_CLAUSE_NEEDS_DATA) fprintf(out, " [NEEDS_DATA]");
                fprintf(out, "\n      Summary: %s\n", cl->summary ? cl->summary : "");
                if (cl->doc && cl->doc[0]) {
                    fprintf(out, "      Doc:     %s\n", cl->doc);
                }
            }
            return;
        }
    }

    fprintf(out, "Unknown command or group '%s'.\n", group_or_word);
}

