void skode_engine_dump(struct skred_engine_s *e, FILE *out, const char *group_filter, int use_long_names) {
    skode_group_t grp = SKODE_GRP_COUNT;
    int v, max_v, var;
    if (!out) out = stdout;
    if (!e) e = &skred_global_engine;
    if (group_filter && group_filter[0] && strcmp(group_filter, "all") != 0) {
        grp = skode_group_from_name(group_filter);
    }
    fprintf(out, "=== SKRED ENGINE DUMP (group: %s, names: %s) ===\n",
            group_filter ? group_filter : "all", use_long_names ? "canonical" : "alias");

    max_v = e->config.voice_max > 0 ? e->config.voice_max : 64;

    /* OSC group */
    if (grp == SKODE_GRP_COUNT || grp == SKODE_GRP_OSC) {
        fprintf(out, "[OSC]\n");
        for (v = 0; v < max_v; v++) {
            if (e->sv.freq && e->sv.freq[v] > 0.0f) {
                int wt = e->sv.wave_table_index ? e->sv.wave_table_index[v] : 0;
                if (use_long_names) {
                    fprintf(out, "  voice %d: wave=%d, freq=%g\n", v, wt, e->sv.freq[v]);
                } else {
                    fprintf(out, "  v%d: w%d f%g\n", v, wt, e->sv.freq[v]);
                }
            }
        }
    }

    /* FILTER group */
    if (grp == SKODE_GRP_COUNT || grp == SKODE_GRP_FILTER) {
        fprintf(out, "[FILTER]\n");
        for (v = 0; v < max_v; v++) {
            if (e->sv.filter_freq && e->sv.filter_freq[v] > 0.0f) {
                float res = e->sv.filter_res ? e->sv.filter_res[v] : 0.0f;
                if (use_long_names) {
                    fprintf(out, "  voice %d: filter_freq=%g, res=%g\n", v, e->sv.filter_freq[v], res);
                } else {
                    fprintf(out, "  v%d: k%g k_res=%g\n", v, e->sv.filter_freq[v], res);
                }
            }
        }
    }

    /* ENV group */
    if (grp == SKODE_GRP_COUNT || grp == SKODE_GRP_ENV) {
        fprintf(out, "[ENV]\n");
        for (v = 0; v < max_v; v++) {
            if (e->sv.amp && e->sv.amp[v] > 0.0f) {
                if (use_long_names) {
                    fprintf(out, "  voice %d: amp=%g\n", v, e->sv.amp[v]);
                } else {
                    fprintf(out, "  v%d: a%g\n", v, e->sv.amp[v]);
                }
            }
        }
    }

    /* SYS group */
    if (grp == SKODE_GRP_COUNT || grp == SKODE_GRP_SYS) {
        fprintf(out, "[SYS]\n");
        for (var = 0; var < ANDS_VAR_MAX; var++) {
            if (global_var[var] != 0.0) {
                fprintf(out, "  $%-3d = %g\n", var, global_var[var]);
            }
        }
    }

    /* SEQ group */
    if (grp == SKODE_GRP_COUNT || grp == SKODE_GRP_SEQ) {
        fprintf(out, "[SEQ]\n");
        fprintf(out, "  master_tick: %llu, current_pattern: %d\n",
                (unsigned long long)seq_master_tick(), seq_current_pattern);
    }
}
